using AcxiomCRM.Data; using AcxiomCRM.Models; using AcxiomCRM.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class OpportunitiesController:BaseController
{
 private readonly ApplicationDbContext _db;private readonly IAuditService _audit; public OpportunitiesController(ApplicationDbContext db,UserManager<ApplicationUser> users,IAuditService audit):base(users){_db=db;_audit=audit;}
 public async Task<IActionResult> Index(string? search,string? stage){var q=_db.Opportunities.AsQueryable();if(IsSales)q=q.Where(x=>x.AssignedTo==CurrentUserId);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.OpportunityName.Contains(search));if(!string.IsNullOrWhiteSpace(stage))q=q.Where(x=>x.Stage==stage);return View(await q.OrderByDescending(x=>x.CreatedDate).ToListAsync());}
 public IActionResult Create()=>View(new Opportunity{ExpectedCloseDate=DateTime.Today.AddDays(30)});
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Opportunity model){if(model.Amount<=0)ModelState.AddModelError(nameof(model.Amount),"Opportunity Amount must be greater than 0.");if(model.Probability<0||model.Probability>100)ModelState.AddModelError(nameof(model.Probability),"Probability must be between 0 and 100.");if(model.Status=="Open"&&model.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(model.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return View(model);model.AssignedTo=CurrentUserId;model.CreatedDate=DateTime.UtcNow;_db.Opportunities.Add(model);await _db.SaveChangesAsync();await _audit.LogAsync("Create","Opportunity",model.OpportunityId.ToString(),newValue:model);return RedirectToAction(nameof(Index));}
 public async Task<IActionResult>Edit(int id){var x=await _db.Opportunities.FindAsync(id);if(x==null||(IsSales&&x.AssignedTo!=CurrentUserId))return NotFound();return View(x);}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,Opportunity model){var x=await _db.Opportunities.FindAsync(id);if(x==null||(IsSales&&x.AssignedTo!=CurrentUserId))return NotFound();if(model.Amount<=0)ModelState.AddModelError(nameof(model.Amount),"Opportunity Amount must be greater than 0.");if(model.ExpectedCloseDate.Date<DateTime.Today&&model.Status=="Open")ModelState.AddModelError(nameof(model.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return View(model);var old=new{x.OpportunityName,x.Amount,x.Stage,x.Probability,x.ExpectedCloseDate,x.Status};x.OpportunityName=model.OpportunityName;x.CustomerId=model.CustomerId;x.LeadId=model.LeadId;x.Amount=model.Amount;x.Stage=model.Stage;x.Probability=model.Probability;x.ExpectedCloseDate=model.ExpectedCloseDate;x.Status=model.Status;await _db.SaveChangesAsync();await _audit.LogAsync("Update","Opportunity",id.ToString(),old,x);return RedirectToAction(nameof(Index));}
 [Authorize(Roles="Admin,Manager")][HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){var x=await _db.Opportunities.FindAsync(id);if(x==null)return NotFound();_db.Opportunities.Remove(x);await _db.SaveChangesAsync();await _audit.LogAsync("Delete","Opportunity",id.ToString(),oldValue:x);return RedirectToAction(nameof(Index));}
}
